\begin{example}[The Rotation Field]
\label{ex:8-17}




\dcref{ch8:8.17}
For $F\colon\mathbb{R}\to\mathbb{R}^2$ given by
$F(t)=(\cos t,\sin t)$, the field $d/dt$ is $F$-related to
\[
Y=x\frac{\partial}{\partial y}-y\frac{\partial}{\partial x}.
\]
\end{example}

